reference_schema.schema:
{
  "type": "object",
  "required": ["deployer"],
  "properties": {
    "deployer": {
      "type": "object",
      "required": ["repoName", "release"],
      "properties": {
        "repoName": {
          "type": "string",
          "description": "Git repository name under github.ibm.com/itz-content",
          "pattern": "^[a-z0-9-]+$"
        },
        "release": {
          "type": "string",
          "description": "Git tag or branch to deploy",
          "minLength": 1
        },
        "parameters": {
          "type": "string",
          "description": "Path to parameters file relative to repository root"
        },
        "ansible": {
          "type": "object",
          "properties": {
            "ansiblePlaybook": {
              "type": "string",
              "description": "Path to Ansible playbook (triggers Ansible mode if non-empty)"
            },
            "requirements": {
              "type": "string",
              "description": "Path to Ansible requirements file"
            }
          }
        },
        "postDeployment": {
          "type": "object",
          "required": ["repoName", "release"],
          "properties": {
            "repoName": {
              "type": "string",
              "description": "Git repository name for post-deployment"
            },
            "release": {
              "type": "string",
              "description": "Git tag or branch for post-deployment"
            },
            "parameters": {
              "type": "string",
              "description": "Parameters file for post-deployment"
            },
            "ansible": {
              "type": "object",
              "properties": {
                "ansiblePlaybook": {
                  "type": "string",
                  "description": "Ansible playbook for post-deployment"
                },
                "requirements": {
                  "type": "string",
                  "description": "Ansible requirements for post-deployment"
                }
              }
            }
          }
        }
      }
    }
  }
}
